 function addAuthoredFog(){if(!window.createCloudFog)return;const sites=[];for(let i=0;i<24;i++){const a=i*Math.PI/12,r=70+8*Math.sin(i*1.7);sites.push({x:Math.cos(a)*r,z:Math.sin(a)*r,size:4.5+(i%4)*.7,outer:true,phase:i*3.7})}for(let i=0;i<12;i++){const a=i*Math.PI/6+.2,r=45+i%3*3;sites.push({x:Math.cos(a)*r,z:Math.sin(a)*r,size:2.2+i%3*.4,phase:12+i*7.3})}for(const [i,p] of [[-4,32],[30,-34],[-43,29],[7,-35],[-28,28]].entries())sites.push({x:p[0],z:p[1],size:1.5+i*.13,inner:true,phase:21+i*17});sites.forEach(async site=>{try{const fog=await window.createCloudFog({atlasUrl:'assets/cloud-fog/fog-flipbook.png',profilesUrl:'assets/cloud-fog/profiles.json',layers:site.outer?2:1,phaseOffset:site.phase});fog.group.position.set(site.x,Math.max(-.9,height(site.x,site.z))+.18,site.z);fog.group.traverse(o=>{if(o.isMesh)clearFogMaterial(o.material)});fog.settings.glow=0;fog.settings.roughness=.65;fog.settings.noise=.35;world.add(fog.group);const shadow=new T.Mesh(new T.PlaneGeometry(site.size*7.8,site.size*3.2,12,8),new T.MeshBasicMaterial({map:softTexture(),color:'#080f14',transparent:true,opacity:0,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,side:T.DoubleSide}));shadow.geometry.rotateX(-Math.PI/2);shadow.userData.outlineIgnore=shadow.userData.navigationIgnore=true;shadow.raycast=()=>{};world.add(shadow);authoredFog.push({...site,fog,shadow,opacity:0,scale:site.size});}catch(e){console.warn('Cloud fog unavailable',e)}})}
